// function makeWhereValue
// create a where clause for and atrocore query based on an incoming object.
// the object has the format:
// { ("_andx" | "_orx" | "fieldname") : ( array | scalar | object ), ... }
// _andx and _orx are indicators of a logical and/or, where x represent an identifying number (to avoid key name clashes)
// if the key is an and/or condition, an object is expected as the value; 
// if the key is a fieldname, an array or a scalar is expected
// the output is a JSON object (stringified)
function makeWhereValue(valueObj) {
  let condition;
  const valueArray = [];
  for (const [key, value] of Object.entries(valueObj || {})) {
    if (key.startsWith("_and") || key.startsWith("_or")) {
      condition = {
        "type": (key.startsWith("_and") ? "and" : "or"),
        "value": makeWhereValue(value)
      };
    } else {
      condition = {
        "type": (Array.isArray(value) ? "in" : "equals"),
        "attribute": key,
        "value": value
      };
    }
    valueArray.push(condition);
  }
  return valueArray;
}

msg.payload = msg.payload || {};

if (msg.entityData) {
  const whereobj = {
    "type": "and",
    "value": makeWhereValue(msg.entityData)
  };

  msg.payload.where = JSON.stringify([whereobj]);
}

if (msg.entitySelect) {
  msg.payload["select"] = msg.entitySelect;
}

msg.headers = { "Authorization": "Bearer " + msg.authToken };
return msg;

// Upstream failures arrive on the normal output. Retry server/transport
// failures a bounded number of times (msg.delay -> the "retry backoff" delay
// node -> back into the request), then raise so the flow's catch handler
// returns the error envelope.
var transportFailure = isNaN(parseInt(msg.statusCode, 10));
var status = transportFailure ? 0 : parseInt(msg.statusCode, 10);
if (status >= 400 || transportFailure) {
    var maxRetries = parseInt(env.get("HTTP_MAX_RETRIES"), 10);
    if (isNaN(maxRetries) || maxRetries < 0) { maxRetries = 2; }
    var attempt = parseInt(msg.retry_6f319e5a075c3efc, 10) || 0;
    var retryable = transportFailure || status >= 500;
    if (retryable && attempt < maxRetries) {
        msg.retry_6f319e5a075c3efc = attempt + 1;
        var backoff = parseInt(env.get("HTTP_RETRY_BACKOFF_MS"), 10);
        if (isNaN(backoff) || backoff < 0) { backoff = 500; }
        msg.delay = backoff * msg.retry_6f319e5a075c3efc;
        return [null, msg];
    }
    var body = (typeof msg.payload === "string") ? msg.payload
        : (msg.payload && msg.payload.error) ? msg.payload.error : "";
    node.error("HTTP " + (transportFailure ? "transport failure" : status) + (body ? ": " + body : ""), msg);
    return null;
}
return msg;

// Deployment settings. The http request node renders its URL with mustache
// against msg only, and mustache HTML-escapes {{ }} values, so the base URLs
// are injected as msg properties and referenced with triple braces {{{ }}}.
msg.atrocoreBaseUrl = env.get("ATROCORE_BASE_URL") || "http://atro-web/api/v1";
msg.alfrescoBaseUrl = env.get("ALFRESCO_BASE_URL") || "http://proxy:8080/alfresco";
var timeout = parseInt(env.get("HTTP_REQUEST_TIMEOUT_MS"), 10);
if (timeout > 0) { msg.requestTimeout = timeout; }
return msg;
